/** What other modules may call in-process: `ctx.use('reviews')` (or `ctx.tryUse` for an optional dependency). */
export interface ReviewsPublicApi {
  /** Ratings for product cards and search results Used by: search, catalog, promotions, graphql. */
  getRatingSummaries(productIds: string[]): Promise<RatingSummary[]>;
  /** Seller quality for offer comparison, featured-offer eligibility and storefronts (also the Official Store profile in content) Used by: offers, sellers, content, graphql. */
  getSellerFeedbackSummary(sellerId: string): Promise<SellerFeedbackSummary>;
  /** Batched getSellerFeedbackSummary (the admin seller list, store seller cards): one answer per id asked for, the same as getSellerFeedbackSummary gives for it, from one read of the summaries. dispatch: false leaves onTimeDispatchPct null and skips shipping's dispatch figures (one shipping call per seller), for lists that do not show them. Used by: sellers. */
  feedbackSummariesForSellers(sellerIds: string[], opts?: { dispatch?: boolean }): Promise<Map<string, SellerFeedbackSummary>>;
  /** Called during a duplicate merge Used by: catalog. */
  moveProductContent(fromProductId: string, toProductId: string): Promise<{ reviews: number, questions: number }>;
  /** Remove proven fake reviews named in an enforcement (same path as consuming trust.enforcement.recorded; publishes reviews.moderation.decided with trustEnforcementId) Used by: trust. */
  removeContentForEnforcement(contentIds: string[], enforcementId: string, reason: string): Promise<number>;
  /** The customer's product reviews, seller feedback, questions, answers and reports they made (with status and moderation outcomes) for the personal data export. Export hook called by customers.build-data-exports Used by: customers. */
  exportCustomerData(input: { customerId: string, accountId: string }): Promise<common.CustomerDataSection[]>;
  /** Published product reviews with filters and sorting (Product.reviews) Used by: graphql. */
  listProductReviews(productId: string, filter: { stars?: number, verifiedOnly?: boolean, withPhotos?: boolean, variantLabel?: string }, sort: string, page: common.PageInput, viewer: common.Actor | null): Promise<common.Page<ProductReview>>;
  /** Published questions with labelled answers (Product.questions) Used by: graphql. */
  listProductQuestions(productId: string, search: string | null, page: common.PageInput): Promise<common.Page<Question>>;
  /** Seller feedback with public seller responses, newest first (Seller.feedback) Used by: graphql. */
  listSellerFeedback(sellerId: string, filter: { sentiment?: string }, page: common.PageInput): Promise<common.Page<SellerFeedback>>;
  /** Review and seller-feedback state per purchased item, batched (OrderItem.reviewStatus) Used by: graphql. */
  reviewStatusForItems(customerId: string, orderItemIds: string[]): Promise<{ orderItemId: string, canReview: boolean, reviewBy: string | null, reviewId: string | null, status: string | null, statusLabel: string | null, rating: number | null, feedbackEligible: boolean, feedbackGiven: boolean }[]>;
  /** Feedback summary of whoever sells each offer, the Official Store included, with on-time dispatch from shipping when enabled Used by: graphql. */
  getOfferSellerRatings(offers: { offerId: string, ownerType: 'official' | 'seller', sellerId: string | null }[]): Promise<Record<string, SellerFeedbackSummary>>;
}

/* ------------------------------------------------------------------ tables (row types) */

/** Rows of this module's spec tables, as repositories read them from its collections (`reviews.<table>`, ctx.mongo.table(name)). */
export interface ReviewsDb {
  /** One review per customer per product (latest delivered purchase); Verified Purchase when linked to a delivered order item */
  product_reviews: {
    id: string;
    product_id: string;
    variant_id: string | null;
    order_item_id: string;
    order_id: string;
    seller_id: string;
    customer_id: string;
    display_name: string;
    show_name: boolean;
    verified: boolean;
    rating: number;
    headline: string;
    body: string;
    media_ids: Json;
    status: string;
    visible: boolean;
    helpful_count: number;
    created_at: Date;
    published_at: Date | null;
    edited_at: Date | null;
  };
  /** One per customer per seller package (order seller group) */
  seller_feedback: {
    id: string;
    seller_id: string;
    order_id: string;
    customer_id: string;
    display_name: string;
    as_described: boolean;
    dispatch_rating: number;
    communication_rating: number | null;
    overall: number;
    sentiment: string;
    comment: string | null;
    status: string;
    visible: boolean;
    /** every item of the package went back: shown, but left out of the seller score */
    refunded: boolean | null;
    created_at: Date;
    edited_at: Date | null;
  };
  seller_responses: {
    id: string;
    target_type: string;
    target_id: string;
    seller_id: string;
    text: string;
    status: string;
    rule_check: Json;
    created_by: string;
    created_at: Date;
    published_at: Date | null;
    editable_until: Date;
  };
  questions: {
    id: string;
    product_id: string;
    customer_id: string;
    display_name: string;
    text: string;
    status: string;
    answer_count: number;
    created_at: Date;
  };
  answers: {
    id: string;
    question_id: string;
    author_kind: string;
    author_id: string;
    seller_id: string | null;
    display_name: string;
    text: string;
    status: string;
    rule_check: Json;
    helpful_count: number;
    created_at: Date;
    published_at: Date | null;
  };
  /** Questions a seller chose not to answer (skipQuestion); only that seller's open list changes */
  question_skips: {
    id: string;
    seller_id: string;
    question_id: string;
    /** member account id */
    skipped_by: string;
    created_at: Date;
  };
  helpful_votes: {
    target_type: string;
    target_id: string;
    customer_id: string;
    helpful: boolean;
    at: Date;
  };
  reports: {
    id: string;
    target_type: string;
    target_id: string;
    moderation_item_id: string;
    reporter_kind: string;
    reporter_id: string | null;
    reason: string;
    note: string | null;
    status: string;
    outcome_text: string | null;
    created_at: Date;
    decided_at: Date | null;
  };
  /** One open item per piece of content under review; reports attach to it */
  moderation_items: {
    id: string;
    content_type: string;
    content_id: string;
    queue: string;
    status: string;
    visibility: string;
    reasons: Json;
    report_count: number;
    first_reported_at: Date;
    decided_at: Date | null;
  };
  moderation_decisions: {
    id: string;
    moderation_item_id: string;
    decision: string;
    reason_code: string;
    message_to_reporter: string | null;
    message_to_author: string | null;
    edit_request: string | null;
    moderator_id: string;
    decided_at: Date;
    appeal_by: Date | null;
    /** trust enforcement this decision executed; reversed with it */
    trust_enforcement_id: string | null;
  };
  /** Content referred to Trust and Risk from moderation (referToTrust; reviews.content.referred). Not a moderation decision: the item stays open */
  referrals: {
    id: string;
    moderation_item_id: string;
    content_type: string;
    content_id: string;
    author_id: string;
    note: string;
    /** staff id */
    referred_by: string;
    referred_at: Date;
  };
  appeals: {
    id: string;
    decision_id: string;
    content_type: string;
    content_id: string;
    by_kind: string;
    by_id: string;
    reason: string;
    status: string;
    reviewer_id: string | null;
    outcome: string | null;
    submitted_at: Date;
    decided_at: Date | null;
  };
  /** Projection updated on publish, edit, removal and merge */
  product_rating_summaries: {
    product_id: string;
    rating_count: number;
    written_count: number;
    sum_ratings: number;
    distribution: Json;
    with_photos: number;
    answered_questions: number;
    updated_at: Date;
  };
  /** Delivered items waiting for a review invitation (decision D-R2): one row per order item from orders.item.delivered; the invites job publishes reviews.invite.due when due_at passes and the item is still unreviewed */
  review_invites: {
    order_item_id: string;
    order_id: string;
    customer_id: string;
    product_id: string;
    /** OFFICIAL_STORE_ID for the Official Store */
    seller_id: string;
    delivered_at: Date;
    due_at: Date;
    state: 'pending' | 'sent' | 'cancelled' | 'reviewed';
    sent_at: Date | null;
    updated_at: Date;
  };
  /** Rolling 12-month projection per seller */
  seller_feedback_summaries: {
    seller_id: string;
    count: number;
    positive: number;
    neutral: number;
    negative: number;
    as_described_yes: number;
    dispatch_sum: number;
    communication_sum: number;
    communication_count: number;
    /** sum of overall ratings in the period: average = overall_sum / count */
    overall_sum: number;
    updated_at: Date;
  };
}

/** This module's tables under their MySQL names, for the typed Kysely handle `ctx.mysql.db` (docs/10 §10.5e). A view is declared by the module that reads it. */
export interface ReviewsTables {
  reviews_product_reviews: ReviewsDb["product_reviews"];
  reviews_seller_feedback: ReviewsDb["seller_feedback"];
  reviews_seller_responses: ReviewsDb["seller_responses"];
  reviews_questions: ReviewsDb["questions"];
  reviews_answers: ReviewsDb["answers"];
  reviews_question_skips: ReviewsDb["question_skips"];
  reviews_helpful_votes: ReviewsDb["helpful_votes"];
  reviews_reports: ReviewsDb["reports"];
  reviews_moderation_items: ReviewsDb["moderation_items"];
  reviews_moderation_decisions: ReviewsDb["moderation_decisions"];
  reviews_referrals: ReviewsDb["referrals"];
  reviews_appeals: ReviewsDb["appeals"];
  reviews_product_rating_summaries: ReviewsDb["product_rating_summaries"];
  reviews_review_invites: ReviewsDb["review_invites"];
  reviews_seller_feedback_summaries: ReviewsDb["seller_feedback_summaries"];
}

